mapper.select:
		SELECT CONCAT(SUBSTRING(NICK_NAME, 1, 1 ),'**') AS "desensitizeName", USER_ID AS "userId" FROM sys_user
		WHERE DEL_FLAG = '0'

            AND is_tenant_admin = #{isTenantAdmin}


            AND tenant_id = #{tenantId}


            AND USER_ID = #{userId}


            AND USER_NAME = #{userName}

SELECT config_id,device_code,tenant_id,industry_code,config_type,user_id,priority,operate_period,preset_priority,patrol_priority,guard_priority
FROM vm_device_operate_auth_config oac
where oac.delete_flag = 0

    and oac.device_code in

        #{id}



    AND oac.device_code = #{deviceCode}


    AND oac.tenant_id = #{tenantId}


    AND oac.industry_code = #{industryCode}


    AND oac.config_type = #{configType}


    AND oac.user_id = #{userId}

SELECT DEPT_NAME FROM sys_dept WHERE DEL_FLAG = 0 AND dept_id IN
#{item}
AND INDUSTRY_CODE = #{industryCode} LIMIT 1
